:root { color-scheme: dark; font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { min-height: 100vh; margin: 0; padding: 40px 20px; color: #f8fafc; background: #0f172a; }
.gallery { max-width: 1180px; margin: 0 auto; }
.gallery h1, .gallery > p { text-align: center; }
.gallery > p { margin-bottom: 30px; color: #94a3b8; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 14px; }
.grid button { display: block; min-height: 44px; padding: 0; overflow: hidden; border: 0; border-radius: 12px; background: #1e293b; cursor: zoom-in; }
.grid img { display: block; width: 100%; aspect-ratio: 1; object-fit: cover; transition: transform .2s; }
.grid button:hover img { transform: scale(1.035); }
button:focus-visible { outline: 3px solid #fbbf24; outline-offset: 4px; }
.lightbox { position: fixed; inset: 0; z-index: 20; display: grid; place-items: center; padding: 20px; background: rgba(2, 6, 23, .94); }
.lightbox[hidden] { display: none; }
.lightbox__panel { position: relative; width: min(100%, 980px); }
.lightbox h2 { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.lightbox img { display: block; width: 100%; max-height: 82vh; border-radius: 12px; object-fit: contain; }
#lightbox-close { position: absolute; top: 10px; right: 10px; z-index: 1; width: 48px; height: 48px; border: 0; border-radius: 50%; color: #ffffff; background: rgba(15,23,42,.78); font-size: 2rem; cursor: pointer; }
@media (prefers-reduced-motion: reduce) { .grid img { transition: none; } }

const images = Array.from({ length: 12 }, (_, index) => ({
  thumb: 'https://picsum.photos/seed/gallery-' + (index + 1) + '/600/600',
  full: 'https://picsum.photos/seed/gallery-' + (index + 1) + '/1200/900',
  alt: '画廊作品 ' + (index + 1)
}));
const gallery = document.querySelector('.gallery');
const grid = document.querySelector('#gallery-grid');
const lightbox = document.querySelector('#lightbox');
const lightboxImage = document.querySelector('#lightbox-image');
const closeButton = document.querySelector('#lightbox-close');
let previousFocus = null;

images.forEach(image => {
  const button = document.createElement('button');
  const element = document.createElement('img');
  button.type = 'button';
  button.setAttribute('aria-label', '查看大图：' + image.alt);
  element.src = image.thumb;
  element.alt = image.alt;
  element.loading = 'lazy';
  button.append(element);
  button.addEventListener('click', () => {
    previousFocus = button;
    lightboxImage.src = image.full;
    lightboxImage.alt = image.alt + '的大图';
    gallery.inert = true;
    lightbox.hidden = false;
    closeButton.focus();
  });
  grid.append(button);
});

function closeLightbox() {
  if (lightbox.hidden) return;
  lightbox.hidden = true;
  gallery.inert = false;
  lightboxImage.removeAttribute('src');
  if (previousFocus) previousFocus.focus();
}

closeButton.addEventListener('click', closeLightbox);
lightbox.addEventListener('click', event => { if (event.target === lightbox) closeLightbox(); });
document.addEventListener('keydown', event => {
  if (event.key === 'Escape') closeLightbox();
  if (event.key === 'Tab' && !lightbox.hidden) {
    event.preventDefault();
    closeButton.focus();
  }
});
